import{_ as a}from"./chunks/main_page.iLigAlA3.js";import{_ as o}from"./chunks/main_page_drag.c4Bat0TW.js";import{_ as e,o as r,c as l,a0 as i}from"./chunks/framework.akKRIpjQ.js";const m=JSON.parse('{"title":"01 · 快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/01-getting-started.md","filePath":"zh/guide/01-getting-started.md"}'),d={name:"zh/guide/01-getting-started.md"};function n(s,t,h,c,u,g){return r(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="_01-·-快速开始" tabindex="-1">01 · 快速开始 <a class="header-anchor" href="#_01-·-快速开始" aria-label="Permalink to &quot;01 · 快速开始&quot;">​</a></h1><blockquote><p>从零打开 V1.0 到完成「第一次穿线提醒」，大约 <strong>5 分钟</strong>。</p></blockquote><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><h3 id="安装-apk-android" tabindex="-1">安装 APK（Android） <a class="header-anchor" href="#安装-apk-android" aria-label="Permalink to &quot;安装 APK（Android）&quot;">​</a></h3><ol><li>在「下载」页面选一个来源，下载 <code>app-release.apk</code></li><li>第一次打开 APK，Android 会拦截&quot;未知来源应用&quot;： <ul><li><code>设置 → 应用 → 特殊权限 → 安装未知应用</code></li><li>选中你的浏览器 / 文件管理器，把&quot;允许此来源&quot;打开</li></ul></li><li>重新点击 APK → <code>仍要安装</code> → <code>完成</code></li></ol><blockquote><p>iOS 用户：当前没有可用构建，详见 <a href="./00-introduction.html#支持平台">00 · 项目介绍</a>。</p></blockquote><h2 id="启动" tabindex="-1">启动 <a class="header-anchor" href="#启动" aria-label="Permalink to &quot;启动&quot;">​</a></h2><p>点击桌面图标进入 AceCrush Craft。首次启动会做三件事：</p><ol><li>初始化本地 SQLite 数据库（球拍档案、穿线日志）</li><li>申请&quot;通知&quot;权限（用于换线提醒）</li><li>直接进入首页 —— <strong>没有账号，不登录</strong></li></ol><blockquote><p>通知被拒绝？别担心 —— 你可以在 <code>设置 → 通知</code> 中重新开启，但<strong>没有通知就没有换线提醒</strong>。</p></blockquote><h2 id="首页-——-四大功能" tabindex="-1">首页 —— 四大功能 <a class="header-anchor" href="#首页-——-四大功能" aria-label="Permalink to &quot;首页 —— 四大功能&quot;">​</a></h2><img src="'+a+'" alt="AceCrush Craft 首页" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>首页布局是顶部两张大卡片 + 中下方的功能宫格：</p><table tabindex="0"><thead><tr><th>顶部卡片</th><th>它做什么</th></tr></thead><tbody><tr><td><strong>AI 测握把尺寸</strong></td><td>拍一张手掌照片 → 推荐握把尺寸</td></tr><tr><td><strong>张力换算</strong></td><td>DT ⇄ RT ⇄ lbs ⇄ kg 互转</td></tr></tbody></table><p>功能宫格里：</p><ul><li><strong>AI 测握把尺寸</strong> — 与顶部卡片一样</li><li><strong>球拍档案</strong> — 你的全部球拍</li><li><strong>穿线记录</strong> — 穿线历史 + 换线提醒</li><li><strong>张力换算</strong> — 与顶部卡片一样</li><li><strong>设置</strong> — 主题 / 单位 / 隐私 / 反馈 / 开源许可</li></ul><blockquote><p>长按宫格的图标拖到顶部卡片就能换顺序；长按拖出宫格变回卡片。<strong>顺序只在你这台设备上生效</strong>。</p></blockquote><img src="'+o+'" alt="首页拖动重排" style="max-width:320px;border-radius:12px;margin:12px 0;"><h2 id="把通知打开-最关键的一步" tabindex="-1">把通知打开（最关键的一步） <a class="header-anchor" href="#把通知打开-最关键的一步" aria-label="Permalink to &quot;把通知打开（最关键的一步）&quot;">​</a></h2><p>不打开通知 → 换线提醒推送不到。<strong>强烈建议在第一时间做完</strong>：</p><ol><li>进「我的」Tab → <code>通知与提醒</code></li><li>把&quot;换线提醒&quot;打开 → Android 系统设置里允许本 App 发送通知</li><li>设置提醒时间窗（默认 <code>09:00</code>，可改 <code>20:00</code> / <code>12:00</code>）</li></ol><blockquote><p>如果你以后不想收到通知，再来关掉就好。</p></blockquote><h2 id="三栏-tab" tabindex="-1">三栏 Tab <a class="header-anchor" href="#三栏-tab" aria-label="Permalink to &quot;三栏 Tab&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tab</th><th>你在这里做什么</th></tr></thead><tbody><tr><td><strong>首页</strong></td><td>四个功能入口（大卡片 + 宫格）+ 当日提醒</td></tr><tr><td><strong>球拍</strong></td><td>档案列表、穿线日志、提醒设置</td></tr><tr><td><strong>我的</strong></td><td>主题 / 语言 / 单位 / 隐私 / 反馈 / 开源许可</td></tr></tbody></table><h2 id="走一遍-加第一支球拍-录一次穿线" tabindex="-1">走一遍：加第一支球拍 + 录一次穿线 <a class="header-anchor" href="#走一遍-加第一支球拍-录一次穿线" aria-label="Permalink to &quot;走一遍：加第一支球拍 + 录一次穿线&quot;">​</a></h2><p>这是最短的&quot;用起来&quot;路径：</p><h3 id="第-1-步-——-加球拍-03-·-球拍档案" tabindex="-1">第 1 步 —— 加球拍（<a href="./03-racquets.html">03 · 球拍档案</a>） <a class="header-anchor" href="#第-1-步-——-加球拍-03-·-球拍档案" aria-label="Permalink to &quot;第 1 步 —— 加球拍（[03 · 球拍档案](./03-racquets)）&quot;">​</a></h3><ol><li>「球拍」Tab → <code>+ 添加球拍</code></li><li>录入最少 4 项：<strong>名称</strong>、<strong>品牌</strong>、<strong>型号</strong>、<strong>拍面</strong></li><li>选填：长度 / 重量 / 平衡点 / 备注</li><li><code>保存</code></li></ol><h3 id="第-2-步-——-录穿线-04-·-穿线记录" tabindex="-1">第 2 步 —— 录穿线（<a href="./04-stringing-log.html">04 · 穿线记录</a>） <a class="header-anchor" href="#第-2-步-——-录穿线-04-·-穿线记录" aria-label="Permalink to &quot;第 2 步 —— 录穿线（[04 · 穿线记录](./04-stringing-log)）&quot;">​</a></h3><ol><li>进入该球拍详情 → <code>穿线记录</code> Tab → <code>+ 添加穿线记录</code></li><li>录入：日期（默认今天）、线材、主磅 / 横磅，可填穿线师 / 备注</li><li><code>保存</code></li></ol><h3 id="第-3-步-——-设换线提醒" tabindex="-1">第 3 步 —— 设换线提醒 <a class="header-anchor" href="#第-3-步-——-设换线提醒" aria-label="Permalink to &quot;第 3 步 —— 设换线提醒&quot;">​</a></h3><p>紧接上一节，在球拍详情页：</p><ol><li><code>设置穿线提醒</code> → 选规则： <ul><li><strong>按时间</strong>（默认 90 天后）</li><li><strong>按打球小时数</strong>（你每周打球 × 时长 → 估算）</li></ul></li><li>选提醒时间窗（用回上面设的那个）</li></ol><blockquote><p>不在 App 里登记任何数据？提醒仍然到点响，但就是空消息（&quot;是时候看看你的拍线了&quot;）。</p></blockquote><h2 id="切换主题与单位" tabindex="-1">切换主题与单位 <a class="header-anchor" href="#切换主题与单位" aria-label="Permalink to &quot;切换主题与单位&quot;">​</a></h2><p>「我的」Tab：</p><ul><li><strong>主题</strong>：跟随系统 / 浅色 / 深色（V1.1 起支持纯黑 OLED）</li><li><strong>单位</strong>：长度 = 毫米 / 英寸；重量 = 克 / 盎司；磅数 = lbs / kg</li><li><strong>语言</strong>：简体中文（V1.0）+ English（V1.0+）</li></ul><blockquote><p><strong>语言设置只影响 App 显示语言</strong>；不会翻译你录入的备注、拍名。</p></blockquote><h2 id="第一次反馈" tabindex="-1">第一次反馈 <a class="header-anchor" href="#第一次反馈" aria-label="Permalink to &quot;第一次反馈&quot;">​</a></h2><p>「我的」Tab → <code>反馈与建议</code>：</p><ul><li>一句话描述问题 → <code>发送</code></li><li>反馈会带 App 版本号与设备基本信息（OS 版本 / 屏幕分辨率，<strong>不</strong>带任何账号信息或你录入的数据）</li></ul><p>详见 <a href="./06-settings-faq.html#反馈">06 · 反馈</a>。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="卸载了再装数据还在吗" tabindex="-1">卸载了再装数据还在吗? <a class="header-anchor" href="#卸载了再装数据还在吗" aria-label="Permalink to &quot;卸载了再装数据还在吗?&quot;">​</a></h3><p><strong>不在</strong>。所有数据存在 App 沙盒目录（Android: <code>/data/data/com.acecrushcraft.app/databases/</code>），卸载即清空。 建议安装 V1.1 之前，先在「设置 → 导出」做一次 JSON 备份。</p><h3 id="ios-什么时候有" tabindex="-1">iOS 什么时候有? <a class="header-anchor" href="#ios-什么时候有" aria-label="Permalink to &quot;iOS 什么时候有?&quot;">​</a></h3><p>暂无 ETA。先把 Android V1.0 / V1.1 打磨到位，iOS 计划中。</p><h3 id="关闭网络可以用吗" tabindex="-1">关闭网络可以用吗? <a class="header-anchor" href="#关闭网络可以用吗" aria-label="Permalink to &quot;关闭网络可以用吗?&quot;">​</a></h3><p>除以下这类外可以：</p><ul><li>反馈发送</li></ul><p>详见 <a href="./00-introduction.html#1-离线优先">00 · 三大基石之离线优先</a> 与 <a href="./06-settings-faq.html#隐私与权限清单">06 · 隐私与权限清单</a>。</p>',51)])])}const f=e(d,[["render",n]]);export{m as __pageData,f as default};
